package Lec4;

public class for_loop_demo {

	public static void main(String[] args) {
		for(int i=1; i<=5; i++) {
			System.out.println(i);	}
		for(int i=1; i<=5;) {
			System.out.println(i);
			i++;
			}
		for(int i=1; i<=5; i++) {
			System.out.println(i);	}
		// TODO Auto-generated method stub

	}

}
